window.HOEREN_TESTS[28] = {"id":"vereine-und-hobbys","name":"Vereine und Hobbys","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Vereinsmitglieder, das nächste Treffen unseres Wanderclubs ist am Sonntag, nicht am Samstag wie sonst. Wir treffen uns um 9 Uhr beim Parkplatz Waldweg. Also nicht Samstag und nicht nur bei schönem Wetter, sondern Sonntag um 9 Uhr. Mitzubringen: gute Wanderschuhe, Wasser, Brotzeit für unterwegs. Bei Regen wird verschoben — sagen wir per WhatsApp Bescheid. Bis Sonntag!","gender":"f","q":"Wann ist das Treffen?","opts":["Sonntag um 9 Uhr.","Bei schönem Wetter immer.","Samstag."],"correct":0},{"transcript":"Hi Lukas, hier ist Tom vom Schachverein. Das Turnier am Wochenende — du hast dich noch nicht angemeldet. Bist du dabei? Die Anmeldegebühr ist 15 Euro, aber du musst sie nicht jetzt überweisen, zuerst die Anmeldung. Es gibt einen Preis von 200 Euro für den Sieger. Letzter Tag ist Freitag, also bitte bis Freitag anmelden. Den Verein verlassen musst du natürlich nicht.","gender":"m","q":"Was muss Lukas tun?","opts":["15 Euro überweisen.","Sich für das Turnier anmelden bis Freitag.","Den Verein verlassen."],"correct":1},{"transcript":"Achtung an alle Sammler! Der Briefmarken-Tausch-Tag am Sonntag wurde verschoben. Wegen einer Veranstaltung in unserem Saal können wir nicht am Sonntag. Neuer Termin: Samstag in zwei Wochen, gleiche Uhrzeit, 14 bis 18 Uhr. Wer kommt, bitte 5 Euro Eintritt mitbringen für die Saalmiete. Bis dann, tschüss!","gender":"f","q":"Wann findet der Tausch-Tag jetzt statt?","opts":["Diesen Sonntag.","Nie wieder.","Samstag in zwei Wochen."],"correct":2},{"transcript":"Hallo Anna, hier ist die Tanzschule. Dein Kurs Salsa für Anfänger startet am 5. April, nicht am 1. April wie ursprünglich. Die Lehrerin war krank, aber sie kommt wieder, die Lehrerin bleibt gleich. Du musst nicht anders bezahlen — der Preis bleibt 180 Euro für 10 Termine. Also nicht der Preis und nicht die Lehrerin haben sich geändert, sondern das Startdatum. Wir sehen uns am 5.!","gender":"f","q":"Was hat sich geändert?","opts":["Der Preis.","Das Startdatum.","Die Lehrerin."],"correct":1},{"transcript":"Liebe Sport-Mitglieder, ein wichtiger Hinweis. Wegen Renovierung der Halle finden alle Trainings ab Montag im neuen Sportzentrum statt — Marktplatz 8, 10 Minuten zu Fuß von der alten Halle. Nicht in der alten Halle und nicht im Park draußen. Auch Parkplatz vorhanden. Die Renovierung dauert 6 Wochen, dann sind wir zurück. Bitte kommen Sie pünktlich, der Weg ist etwas länger.","gender":"m","q":"Wo finden die Trainings jetzt statt?","opts":["Im Park draußen.","In der alten Halle.","Im neuen Sportzentrum am Marktplatz."],"correct":2}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer ist Mitglied wo? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Frank","gender":"m","text":"Hallo! Diese Woche ist wieder Vereinsabend bei uns."},{"speaker":"Birgit","gender":"f","text":"Fast jeder in der Familie hat schon einen festen Termin."},{"speaker":"Frank","gender":"m","text":"Ich lege den Zettel mit den Namen auf den Tisch."},{"speaker":"Birgit","gender":"f","text":"Du bleibst im Schachverein, Frank. Du spielst dienstags mit den Nachbarn."},{"speaker":"Frank","gender":"m","text":"Tanzt noch jemand bei uns im Tanzverein?"},{"speaker":"Birgit","gender":"f","text":"Nein. Im Tanzverein ist keiner von uns."},{"speaker":"Frank","gender":"m","text":"Du singst im Chor, Birgit. Du übst donnerstags in der Kirche."},{"speaker":"Birgit","gender":"f","text":"Mit dreißig Leuten klingt es dort richtig voll."},{"speaker":"Frank","gender":"m","text":"Lukas kommt abends oft mit nassen Schuhen nach Hause."},{"speaker":"Birgit","gender":"f","text":"Lukas spielt im Fußballverein. Zweimal pro Woche trainiert er hart."},{"speaker":"Frank","gender":"m","text":"Lisa übt seit Tagen einen langen Text im Zimmer."},{"speaker":"Birgit","gender":"f","text":"Lisa ist im Theaterverein. Im Frühling spielt sie die Nachbarin."},{"speaker":"Frank","gender":"m","text":"Wollen wir sonntags in den Wanderclub?"},{"speaker":"Birgit","gender":"f","text":"Nein. Den Wanderclub wählen wir auch nicht."},{"speaker":"Frank","gender":"m","text":"Sara trägt fast immer eine Kamera um den Hals."},{"speaker":"Birgit","gender":"f","text":"Sara ist im Foto-Club. Im Mai zeigt sie Bilder in der Stadt."},{"speaker":"Frank","gender":"m","text":"Ich lege den Plan neben die Kaffeemaschine."},{"speaker":"Birgit","gender":"f","text":"Dann sehen wir ihn jeden Morgen sofort."}],"options":[{"letter":"a","text":"Theaterverein"},{"letter":"b","text":"Tanzverein"},{"letter":"c","text":"Musikverein"},{"letter":"d","text":"Foto-Club"},{"letter":"e","text":"Wanderclub"},{"letter":"f","text":"Buchklub"},{"letter":"g","text":"Fußballverein"},{"letter":"h","text":"Chor"},{"letter":"i","text":"Schachverein"}],"items":[{"person":"Frank","correct":"i"},{"person":"Birgit","correct":"h"},{"person":"Lukas","correct":"g"},{"person":"Lisa","correct":"a"},{"person":"Sara","correct":"d"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Mitarbeiter","gender":"m","text":"Willkommen im Sportverein. Was möchten Sie spielen — Tennis, Volleyball, oder beide?"},{"speaker":"Interessent","gender":"m","text":"Ich überlege zwischen Tennis und Volleyball. Beides auf einmal ist viel."},{"speaker":"Mitarbeiter","gender":"m","text":"Tennis ist Einzelsport, Volleyball Teamsport. Beides gut, aber andere Energie. Beide Kurse zusammen sind teuer."},{"speaker":"Interessent","gender":"m","text":"Ich mag Mannschaftssport. Volleyball dann, nicht Tennis und nicht beide."},{"speaker":"Mitarbeiter","gender":"m","text":"Gerne, Volleyball. Training ist Dienstag und Donnerstag. Bis bald!"}],"q":"Welche Sportart wählt er?","opts":["Volleyball.","Tennis.","Beide."],"correct":0},{"lines":[{"speaker":"Trainerin","gender":"f","text":"Guten Tag, wann möchten Sie kommen — unter der Woche oder am Wochenende?"},{"speaker":"Schülerin","gender":"f","text":"Wann sind die Anfänger-Kurse? Montag, Samstag oder Sonntag?"},{"speaker":"Trainerin","gender":"f","text":"Montag und Mittwoch um 18 Uhr, oder Samstag um 10 Uhr morgens. Sonntag morgens haben wir keinen Anfänger-Kurs."},{"speaker":"Schülerin","gender":"f","text":"Samstag morgens — ich arbeite unter der Woche. Montag und Mittwoch um 18 Uhr geht nicht, Sonntag auch nicht."},{"speaker":"Trainerin","gender":"f","text":"Dann Samstag 10 Uhr. Ich schreibe Sie auf die Liste."}],"q":"Wann sind die Anfänger-Kurse für die Schülerin?","opts":["Samstag 10 Uhr.","Mo und Mi 18 Uhr.","Sonntag morgens."],"correct":0},{"lines":[{"speaker":"Kundin","gender":"f","text":"Guten Tag, ich möchte ein Hobby anfangen, aber nicht teuer. Stricken, Yoga, oder soll ich weiter suchen?"},{"speaker":"Mitarbeiterin","gender":"f","text":"Stricken ist sehr beliebt. Material kostet wenig. Yoga geht auch günstig, Sie müssen nicht weiter suchen."},{"speaker":"Kundin","gender":"f","text":"Stricken ist mir zu altmodisch. Was ist mit Yoga? Weiter suchen will ich eigentlich nicht."},{"speaker":"Mitarbeiterin","gender":"f","text":"Yoga-Matte und Video — sehr günstig. Online viele kostenlose Stunden. Nicht stricken."},{"speaker":"Kundin","gender":"f","text":"Yoga dann. Danke, das reicht mir, ich suche nicht weiter."}],"q":"Welches Hobby wählt die Kundin?","opts":["Stricken.","Yoga.","Sie sucht weiter."],"correct":1},{"lines":[{"speaker":"Sohn","gender":"m","text":"Papa, ich möchte Schlagzeug lernen. Oder geht auch Klavier oder Gitarre?"},{"speaker":"Vater","gender":"m","text":"Schlagzeug ist laut. Vielleicht Klavier? Gitarre wäre auch möglich."},{"speaker":"Sohn","gender":"m","text":"Klavier ist langweilig. Schlagzeug ist zu laut für die Nachbarn. Aber Gitarre wäre auch okay."},{"speaker":"Vater","gender":"m","text":"Gitarre passt besser zu uns. Wir kaufen eine, nicht Schlagzeug und nicht Klavier."},{"speaker":"Sohn","gender":"m","text":"Super, dann Gitarre. Wann gehen wir ins Geschäft?"}],"q":"Welches Instrument lernt der Sohn?","opts":["Schlagzeug.","Klavier.","Gitarre."],"correct":2},{"lines":[{"speaker":"Vereinsmitglied","gender":"m","text":"Wann ist unser nächstes Treffen — Donnerstag wie geplant, oder später?"},{"speaker":"Vereinsvorsitzende","gender":"f","text":"Eigentlich nächsten Donnerstag, aber das musste verschoben werden. Nicht nächste Woche komplett ausfallen."},{"speaker":"Vereinsmitglied","gender":"m","text":"Auf wann? Freitag, oder wirklich erst nächste Woche?"},{"speaker":"Vereinsvorsitzende","gender":"f","text":"Freitag, gleiche Uhrzeit. Ich habe es schon allen geschrieben. Nicht Donnerstag wie geplant."},{"speaker":"Vereinsmitglied","gender":"m","text":"Bei mir kam keine Nachricht. Aber gut, Freitag dann, nicht nächste Woche."}],"q":"Wann ist das Treffen?","opts":["Donnerstag wie geplant.","Freitag.","Nächste Woche."],"correct":1}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Klein, dem Vorsitzenden eines Sport-Vereins. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Herr Klein, Sie sind Vorsitzender des SV Adler seit 8 Jahren. Wie ist diese Position entstanden?"},{"speaker":"Klein","gender":"m","text":"Ich war schon 15 Jahre normales Mitglied und habe Fußball gespielt. Als der alte Vorsitzende aufgehört hat, haben mich die Mitglieder gefragt. Erst wollte ich nicht — zu viel Verantwortung neben dem Beruf. Aber ich habe ja gesagt."},{"speaker":"Reporter","gender":"m","text":"Was sind Ihre Aufgaben?"},{"speaker":"Klein","gender":"m","text":"Alles organisieren! Trainings-Pläne, Spiele, Reisen zu anderen Vereinen, Finanzen, neue Mitglieder werben. Auch Konflikte zwischen Spielern lösen — das ist manchmal das Anstrengendste."},{"speaker":"Reporter","gender":"m","text":"Wie viele Mitglieder hat der Verein?"},{"speaker":"Klein","gender":"m","text":"120 — davon 80 aktive Spieler. Vor 8 Jahren hatten wir nur 60 Mitglieder. Wir sind also gewachsen. Viele Kinder kommen jetzt — wir haben mehrere Jugend-Mannschaften."},{"speaker":"Reporter","gender":"m","text":"Sind Sie ehrenamtlich tätig?"},{"speaker":"Klein","gender":"m","text":"Ja, komplett. Niemand im Verein wird bezahlt — alle machen das aus Liebe zum Sport. Etwa 10 Stunden pro Woche investiere ich, manchmal mehr."},{"speaker":"Reporter","gender":"m","text":"Spielen Sie selbst noch Fußball?"},{"speaker":"Klein","gender":"m","text":"Nicht mehr im Verein — ich bin 55 und das wäre zu hart. Aber ich spiele am Sonntag mit Freunden Hobbyfußball. Das schadet zwar meinem Knie, aber ich kann nicht ohne."}],"items":[{"q":"Herr Klein war früher Spieler im Verein.","correct":"ja"},{"q":"Konflikte zwischen Spielern sind manchmal sehr anstrengend.","correct":"ja"},{"q":"Der Verein hat heute weniger Mitglieder als vor 8 Jahren.","correct":"nein"},{"q":"Im Verein werden alle Mitarbeiter bezahlt.","correct":"nein"},{"q":"Er spielt im Vereinsteam noch Fußball.","correct":"nein"}]}]};
